CREATE TABLE IF NOT EXISTS rl."bs_gs_gestantes" (
  "id_fila" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "fila" integer NOT NULL,
  "id" double precision,
  "codigo" extensions.citext,
  "dni" extensions.citext,
  "nombre" extensions.citext,
  "empresa" extensions.citext,
  "fundo" extensions.citext,
  "cargo" extensions.citext,
  "sede" extensions.citext,
  "fecha_comunicacion" timestamp,
  "fecha_probable_parto" timestamp,
  "fecha_parto_real" timestamp,
  "dias_prenatal" double precision,
  "dias_adicionales" double precision,
  "descanso_pre_inicio" timestamp,
  "descanso_pre_fin" timestamp,
  "descanso_post_inicio" timestamp,
  "descanso_post_fin" timestamp,
  "lactancia_hasta" timestamp,
  "riesgo_puesto" extensions.citext,
  "reubicada" extensions.citext,
  "fecha_reubicacion" timestamp,
  "puesto_reubicada" extensions.citext,
  "certificado_citt" extensions.citext,
  "subsidio_tramitado" extensions.citext,
  "lactario" extensions.citext,
  "responsable" extensions.citext,
  "observaciones" extensions.citext,
  "estado" extensions.citext,
  "motivo_cierre" extensions.citext,
  "fecha_cierre" timestamp,
  "created_by" extensions.citext,
  "created_at" timestamp,
  "updated_by" extensions.citext,
  "updated_at" timestamp,
  "anulado" extensions.citext,
  "otros" extensions.citext,
  "actualizado" timestamp DEFAULT (now() at time zone 'utc') NOT NULL,
  PRIMARY KEY ("id_fila")
);
CREATE UNIQUE INDEX IF NOT EXISTS "ix_bs_gs_gestantes_ux_bs_gs_gestantes_fila" ON rl."bs_gs_gestantes" ("fila");
